insert into pubcar_trip_car_passenger(passenger_id, user_id, passenger_name, passenger_department, passenger_position, num_id, b_id)
select passenger_id, user_id, passenger_name, passenger_department, passenger_position, num_id, b_id
from business_pubcar_trip_car_passenger


        and b_id= #{bId}


