mapper.select:
select t.passenger_name,t.passenger_name passengerName,t.create_time,t.create_time
createTime,t.passenger_tel,t.passenger_tel passengerTel,t.passenger_id,t.passenger_id passengerId,t.b_id,t.b_id
bId
from pubcar_trip_car_passenger t


        t.status_cd = #{statusCd}


        t.passenger_name= #{passengerName}


        and t.create_time= #{createTime}


        and t.passenger_tel= #{passengerTel}


        and t.passenger_id= #{passengerId}


        and t.b_id= #{bId}


order by t.create_time desc

    limit #{page}, #{row}

